if (velocities.size() != masses.size()) {
    // Mismatched input sizes; cannot compute kinetic energy reliably.
    // Return 0.0 as a safe default.
    return 0.0;
}
double ke = 0.0;
for (size_t i = 0; i < velocities.size(); ++i) {
    // Kinetic energy for a particle: (1/2) * m * v^2
    // Use lengthSquared() to avoid an unnecessary sqrt.
    ke += 0.5 * masses[i] * velocities[i].lengthSquared();
}
